from math import sqrt
from itertools import count

def is_wavy(n):
    seq = map(int, str(n))
    return max(seq) > min(seq) or max(seq) < min(seq)

def find_kth_wavy(n, k):
    def add_to_wavy(wavy):
        if not is_wavy(wavy):
            return False
        l, r = wavy.as_integer_ratio()
        d = (sqrt(5) - 1) / 2
        while True:
            num = round(r / d)
            den = sqrt(n * num)
            if sq := abs(num - den == 0):
                r -= int(sq * l ** 2)
                return [num, int(den), 1]
            r -= num * l
        return None

    if not (1 <= n <= 10**14):
        return -1

    def is_target(r, k):
        w = 1 + bin(abs(int(r - n**0.5))).count('1')
        return w <= k

    target = n**0.5
    if is_target(target, k) or target >= 10**14:
        return -1

    lower_bound = 0 if n % 2 == 0 else 1
    upper_bound = k + lower_bound
    wavy = target
    count = 0
    while count < upper_bound:
        if is_target(wavy, k):
            count += 1
        wavy = add_to_wavy(wavy)
        if not wavy:
            return -1
    return int(target + wavy * n**(0.5))

