def find_shortest_route():
    t = int(input().strip())
    results = []
    for _ in range(t):
        n = int(input().strip())
        city_colors = list(map(int, input().strip().split()))
        final_colors = list(map(int, input().strip().split()))
        roads = []
        for _ in range(n - 1):
            u, v = map(int, input().strip().split())
            roads.append((u - 1, v - 1))

        colors_needed = {city: color for city, color in zip(range(n), final_colors)}

        def dfs(city, path_length, prev_path):
            if path_length == n:
                return True
            for next_city, _ in roads:
                if next_city == city or colors_needed[next_city] != final_colors[next_city]:
                    continue
                if colors_needed[prev_path[-1]] != city_colors[prev_path[-1]]:
                    continue
                if dfs(next_city, path_length + 1, next_city):
                    return True
                colors_needed[next_city] = final_colors[next_city]
            return False

        paths_taken = 0
        is_possible = False
        best_length = float('inf')
        best_path = []

        for start_city in range(n):
            if dfs(start_city, 1, start_city):
                is_possible = True
                best_length = min(best_length, 2**paths_taken)
                best_path = [city_colors[start_city]] + best_path
                paths_taken += 1
                break

        if not is_possible:
            results.append("No")
        else:
            results.append("Yes")
            results.append(str(best_length))
            results.append(' '.join(map(str, best_path)))

    for result in results:
        print(result)

