from itertools import groupby
from math import gcd
from operator import mul

def maximum_gcd_subarray(A, k):
    # Calculate the greatest common divisor (GCD) of all possible subarrays of size k
    subgroup_gcds = [gcd(subarray) for subarray in A[:k]]
    max_gcd = max(subgroup_gcds)

    # If the maximum subgroup GCD is 1, return all elements as the answer
    if max_gcd == 1:
        return [1] * len(A)

    # Group the elements of A by the GCD of consecutive elements
    grouped_subarrays = [[g] for _, g in groupby(subgroup_gcds, lambda x: x == max_gcd)]

    results = []
    for eq, _ in enumerate(grouped_subarrays):
        for a, b in product(grouped_subarrays[eq][::-1], range(k - 1, -1, -1)):
            for _ in range(a[0] - 1):
                results.append((a[1] * [-1])[-a[0] + b])
    return [1] + list(chain(*results))

T = int(input())
for _ in range(T):
    N = int(input())
