def is_valid_diagonal(n, m, edges):
    adj_list = [[] for _ in range(n)]
    for a, b in edges:
        adj_list[a-1].append(b-1)
        adj_list[b-1].append(a-1)
    return all(len(adj) - len([a for a in adj if a != 0]) == 2 for adj in adj_list.values())

def color_regions(vertices, diagonals):
    adj_list = [set() for _ in range(vertices)]
    for a, b in diagonals:
        adj_list[a-1].add(b-1)
        adj_list[b-1].add(a-1)
    output = []
    used = [False] * vertices
    used[0] = True
    stack = [0]
    lowest_points = set()
    while stack:
        current = stack.pop()
        for neighbor in adj_list[current]:
            if not used[neighbor]:
                used[neighbor] = True
                lowest_points.add(neighbor + 1)
                stack.append(neighbor)
    least_important = []
    for current, neighbors in enumerate(adj_list):
        neighbors = [n for n in neighbors if n + 1 not in neighbors]
        contiguous = [low for low in neighbors if low + 1 not in contiguous]
        if neighbors:
            contiguous.append(lowest_points.pop())
        output.append(len(contiguous))
    return output

