def count_partitions(s):
    MOD = 10**9 + 7
    n = len(s)
    dp = [1] + [0] * (n // 2)
    for i in range(n):
        for j in range(n // 2 - 1, max(-1, i // 2 - n // 4), -1):
            if i + 2 * j >= n or not s[i + i - 2 * j] == s[i + i - 2 * j + 2]:
                break
            dp[i // 2] = (dp[i // 2] + dp[j] * (2 - (j == 0))) % MOD
    return dp[len(s) // 2] if len(s) % 2 == 0 else 0

