            mid_point = index // 2
            left_partition = s[:current_index]
            right_index = len(s) - index
            remaining_substring = s[current_index:right_index]

            left_substring_reversed = s[current_index:index]
            left_sorted_substring = ''.join(sorted(left_substring_reversed))
            right_substring_reversed = s[(index + remaining_substring.index(max(remaining_substring))) + 1:right_index]
            right_sorted_substring = ''.join(sorted(right_substring_reversed))

            if left_sorted_substring == right_sorted_substring:
                ways += partition(s, left_index=index, current_index=current_index + 1) if mid_point - 1 // 2 > index else 0

            for new_partition_length in (left_index, mid_point - 1 - left_index):
                new_start_index = current_index - mid_point + 1 + new_partition_length
                new_end_index = current_index + right_index
