def find_profile_mask(mask):
    n = len(mask)
    profile = []
    last_filled = 0

    for i in range(n):
        if mask[i] == '#':
            if last_filled != 0:
                profile.append(last_filled)
            last_filled = 0
        else:
            if i > 0 and mask[i-1] == '#':
                last_filled += 1

    if last_filled != 0:
        profile.append(last_filled)

    profile_sorted = sorted(profile, reverse=True)

    min_val = min(profile_sorted)
    max_val = max(profile)

    # Calculate the possible range for a profile
    range_min = min_val + len(profile) - 1
    range_max = max_val + (1 - max_val)

    # Find the profile in the range
    found = False
    for profile_min in range(range_min, range_max + 1):
        if sorted(profile_sort(profile_min)) == sorted(profile):
            found = True
            break

    if not found:
        return 0
    else:
        return profile

def profile_sort(profile):
    return ['-'.join([str(x) for x in profile[i:i+3]]) if i+3 <= len(profile) else str(profile[i]) for i in range(0, len(profile), 3)]

