import math

def find_optimal_sequence_and_price(n, q, a, b, xs):
    dp = [0] * (q + 1)
    dp[0] = 1
    for i in range(n):
        if i == 0:
            ys = xs[i] * a / (q + 1)
        else:
            ys = math.floor(xs[i] * a / (q + 1))
        if ys > q:
            ys = q
        dp[ys] += 1
        for j in range(1, min(ys, q // a) + 1):
            if a * j <= q:
                dp[j + a] += dp[j]

    total = sum(dp) - 1
    min_price = math.inf
    optimal_dp = dp
    for y1 in range(1, q + 1):
        price = 0
        for y2 in range(1, max(y1, [a, q // a + 1]) + 1):
            price += dp[y2]
        if price < min_price:
            min_price = price
            optimal_dp = [y1] + [min(y1 + a, q + 1) if i > 0 else y1 for i in range(n - 1)]

    return optimal_dp, min_price

