def max_xor(A, B):
    max_xor = 0
    for i in range(len(A)):
        max_xor |= A[i]
        for j in range(i + 1, len(A)):
            max_xor |= A[i] | A[j]
        for k in range(1 << (j - i)):
            is_all_zero = True
            is_all_one = True
            for l in range(i, j + 1):
                if (k & (1 << l - i)) > 0 and (k >> (l - i) & 1) == 1:
                    is_all_zero = False
                elif (k >> (l - i) & 1) == 1:
                    is_all_one = False
            if is_all_zero or is_all_one:
                max_xor = max(max_xor, (k | (1 << i) | (1 << j)))
    return max_xor

