from collections import defaultdict, deque
import heapq
from typing import List

def min_distance(wormholes: List[List[int]], space_ships: int) -> List[int]:
    graph = defaultdict(list)
    dist = [float('inf')] * (space_ships + 1)
    for u, v in wormholes:
        graph[u].append(v)
        graph[v].append(u)
    dist[space_ships] = 0
    q = deque([(space_ships, 0)])
    while q:
        node, d = q.popleft()
        for n in graph[node]:
            if dist[node] + 1 < dist[n]:
                dist[n] = dist[node] + 1
                heapq.heappush(q, (n, dist[n]))
    return dist

def max_profit(attack_strength: int, fuel: int, defense: int) -> int:
    profit = [0] * (attack_strength + 1)
    for ship in range(attack_strength, 0, -1):
        if fuel >= min_distance(wormholes, ship) + 1:
            if fuel - min_distance(wormholes, ship) - 1 >= defense * len(wormholes):
                profit[ship] = -defense * len(wormholes)
                for base in range(len(wormholes)):
                    if fuel - min_distance(wormholes, ship) - 1 >= defense + wormholes[base]:
                        profit[ship] -= defense + wormholes[base]
            else:
                profit[ship] = -defense * len(wormholes) + fuel - min_distance(wormholes, ship)
    return max(profit)

def main(n: int, m: int, wormholes: List[List[int]], s_spaceships: int, b_bases: int, k_dependencies: List[List[int]]) -> int:
    graph = defaultdict(list)
    for u, v in wormholes: 
        graph[u].append(v)
        graph[v].append(u)
    for u, d, g in b_bases: 
        graph[u].append((d, -g))
    shortest_distances = min_distance(graph, s_spaceships)
    space_ships = []
    for ship in range(s_spaceships):
        x, a, f, p = wormholes[ship]
        space_ships.append((x, a, f, p))
    final_profit = 0
    for s1, s2 in k_dependencies:
        dependent_profits = set()
        combined_profit = 0
        for ship in range(s1, s1 + attack_strength + 1):
            profitable = True
            for base, dist in graph[space_ships[ship][0]]:
                if min_distance(graph, space_ships[ship][1]) == dist:
                    combined_profit += max_profit(space_ships[ship][1], 0, base * dist - space_ships[ship][2]) + base
            if fuel >= min_distance(graph, space_ships[s1][1]) + 1:
                final_profit = max(final_profit, combined_profit + max_profit(space_ships[s1][1], 0, base * (min_distance(graph, space_ships[s1][1]) + 1) * (shortest_distances[s1]) - base))
            for base, dist in graph[space_ships[s1][0]][space_ships[ship][0]]:
                if min_distance(graph, space_ships[ship][1]) == dist:
                    combined_profit += max_profit(space_ships[ship][1], 0, base)
            for i in range(len(wormholes)):
                if fuel - min_distance(graph, space_ships[s1][1]) - 1 >= defense + wormholes[i]:
                    dependent_profits.add(i)
        for ship in space_ships[s1:s1 + attack_strength]:
            if ship in dependent_profits:
                dependent_profits.remove(ship)

    return final_profit

