    for u, neighbors in edge_graph.items():
        if len(neighbors) > 1:
            parents = {u}
            while u not in order:
                parents.add(u)
                u = u - 1 if u else 1 
                if u in neighbors:
                    neighbors.remove(u)
            order.insert(0, u)
            for child in neighbors:
                tree[u].append(child)

