def min_arithmetic_progressions(arr):
    if len(arr) == 1:
        return 1
    progressions = 1
    current_index = 0
    for i in range(len(arr)):
        if arr[i] != -1:
            current_index = i
        elif i != 0 and arr[i-1] != -1:
            progressions += 1
        else:
            progressions = 1
        excess = 0
        for j in range(i + 1, len(arr)):
            if arr[j] == -1:
                excess -= 1
            if arr[j] != -1:
                excess += 1
            if excess > progressions:
                return progressions + 1
            if excess < progressions:
                progressions += 1
            if excess == progressions and current_index < i:
                excess -= 1
        current_index = i
    return progressions


