def find_matching_profile(n, mask, k):
    # Count the number of contiguous filled cells in the mask
    filled_count = mask.count('#')

    if filled_count % k != 0 or filled_count == k:
        return -1

    profile_length = filled_count // k
    kth_following = filled_count

    pk = []
    for cell in mask:
        if pk and cell in pk[-1]:
            kth_following -= 1
            if kth_following <= 0:
                break
        pk.append(cell)

    return profile_length, pk


def solve_nonogram(n, mask):
    if mask.count('_') == n:
        return [-1]

    k = mask.count('#')
    if mask.count('_') + k > n:
        return [-1]

    return find_matching_profile(n, mask, k)


