def count_split_part_ways(s):
    MOD = 10**9 + 7
    n = len(s)
    prefix_sums = [0] * (n + 1)
    bad = 0
    for i in range(n):
        if s[i] == 'b':
            bad += 1
        prefix_sums[i + 1] = bad

    # Calculate counts in an auxiliary array for all substrings.
    @lru_cache(None)
    def ways(i, j):
        if i > j:
            return 1
        if prefix_sums[i + 1] == (j - i + 1):
            return ways(0, i - 1) * ways(i + 1, j)
        return 0

    return ways(0, n - 1) % MOD

