import math

def find_profile(mask):
    n = len(mask)
    if mask.count("#") != n:
        return -1

    row_palindrome = list(mask)
    for i in range(1, n//2 + 1):
        if row_palindrome[:i] != row_palindrome[i:][::-1]:
            return -1

    col_palindrome = [mask[j-i] for j in range(n) for i in range(n) if n//2 > j-i > i]
    if col_palindrome != col_palindrome[::-1]:
        return -1

    k = 2 ** 16
    values = [0] * k

    for length in range(0, 1 << n):
        j = 0
        for i in range(n):
            if length & 1 << i:
                values[j] += int(row_palindrome[i])
                j += 1

        temp = [0] * k
        ks = 2 ** 16
        for i in range(n):
            temp[ks] = int(col_palindrome[(i + int(values[k-ks // 2])) % n])
            ks -= 1

        new_length = 0
        for i in range(ks, ks + n):
            new_length += int(values[i % n])
        if new_length == k:
            temp[col_palindrome.index(1)] = 1

        for i in range(1, n):
            if temp[(i + 1) % n] == 1:
                if i > 1:
                    new_length -= int(row_palindrome[(i + i) % n])
                    new_length += int(row_palindrome[n - i] * 4)
                else:
                    new_length += int(row_palindrome[(i + n) % n])

                if new_length == k - 1 or (new_length == k and i == n // 2):
                    ks = i + 1
                    temp[col_palindrome.index(1) + 1] = 1
                    for i in range(1, n):
                        if temp[(i + (i + 1)) % n] == 1:
                            if i >= n // 2:
                                temp[col_palindrome.index(1) + 2] = 1
                                temp[col_palindrome.index(1) + 1] = 0

                                if 2 * (temp[col_palindrome.index(1) + 1] + temp[col_palindrome.index(1) + 2]) == 2:
                                    temp[col_palindrome.index(1) + 1] = 0

        if values[ks % n] == k:
            temp[col_palindrome.index(1)] = 2
            if k > 2:
                temp[col_palindrome.index(1)] += 1
        elif values[ks] == k:
            temp[col_palindrome.index(1)] = 3
            if k > 3:
                for i in range(k-3, k):
                    temp[i-3] = 2
        values[k] = temp[col_palindrome.index(1)]

    return [k-values[k]] + values[0:k-2]

