from collections import defaultdict

def main():
    n, k = map(int, input().split())
    connections = [list(map(int, input().split())) for _ in range(k)]
    friendships = defaultdict(list)

    # Create a network of friends
    for friend in connections:
        friendships[friend[0]].append(friend[1])
        friendships[friend[1]].append(friend[0])

    # Calculate tokens for each member
    tokens = [0] * n
    all_friends = set()
    for i, friend in enumerate(friendships):
        connections = friendships[friend]
        while tokens[friend] > 0:
            tokens[friend] = 1
            for f in [friend, friendship[1] for friendship in connections]:
                all_friends.add(f)
                tokens[f] = 0 if tokens[f] < 3 else 2

        tokens[friend] += 1
        for f in connections:
            all_friends.add(f)
            tokens[f] = 0

    # Remove already granted tokens from the primary token holder
    for f in all_friends:
        if tokens[f] < 2:
            tokens[f] = 0

    print(sum(tokens) - tokens[0])
    for f in all_friends:
        if tokens[f] < 2:
            print(f, tokens[f], 1)
        else:
            print(f, tokens[f], 2)
