def count_tuples(N):
    count = 0
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            for k in range(1, N + 1):
                for l in range(1, N + 1):
                    if (i/j + k/l).is_integer():
                        count += 1
    return count

